instance MessageEncode RequiredChild24 where
  buildMessage msg =
    (maybe mempty (\v -> archVarint 8 (fromIntegral v)) msg.requiredChild24Value)
    <> (maybe mempty (\v -> archString 18 v) msg.requiredChild24Label)
    <> encodeUnknownFields msg.requiredChild24UnknownFields

instance MessageSize RequiredChild24 where
  messageSize msg =
    (maybe 0 (\v -> archVarintSize (fromIntegral v)) msg.requiredChild24Value)
    + (maybe 0 (\v -> archStringSize v) msg.requiredChild24Label)
    + unknownFieldsSize msg.requiredChild24UnknownFields

instance MessageDecode RequiredChild24 where
  {-# INLINE messageDecoder #-}
  messageDecoder = loop Nothing Nothing []
    where
      loop acc_0 acc_1 acc_unknown_ = withTagM
        (pure (RequiredChild24 {requiredChild24Value = acc_0, requiredChild24Label = acc_1, requiredChild24UnknownFields = reverse acc_unknown_}))
        (\fn wt -> case fn of
          1 | wt == 0 -> do
            v <- (fromIntegral <$> decodeFieldVarint)
            loop (Just v) acc_1 acc_unknown_
          2 | wt == 2 -> do
            v <- decodeFieldString
            loop acc_0 (Just v) acc_unknown_
          _ -> do
            uf <- captureUnknownField fn (toEnum wt)
            loop acc_0 acc_1 (uf : acc_unknown_))

